30	describe('Test object compare', () => {
31	    describe('Test valueObjectCompare', () => {
32	        it('range and criteria', () => {
33	            const rangeNumber = new ArrayValueObject(/*ts*/ `{
34	                1;
35	                4;
36	                44;
37	                444
38	            }`);
39	
40	            const criteria = new StringValueObject('>40');
41	
42	            const resultObjectValue = transformToValue(valueObjectCompare(rangeNumber, criteria).getArrayValue());
43	            expect(resultObjectValue).toStrictEqual([[false], [false], [true], [true]]);
44	        });
45	
46	        it('range with wildcard asterisk', () => {
47	            const criteriaList = [
48	                'test*',
49	                '=test*',
50	                '>test*',
51	                '>=test*',
52	                '<test*',
53	                '<=test*',
54	                'test?',
55	                '=test??',
56	                '>test?',
57	                '>=test??',
58	                '<test?',
59	                '<=test??',
60	            ];
61	
62	            const result = [
63	                [[false], [true], [true], [false]],
64	                [[false], [true], [true], [false]],
65	                [[false], [true], [true], [true]],
66	                [[false], [true], [true], [true]],
67	                [[true], [false], [false], [false]],
68	                [[true], [false], [false], [false]],
69	                [[false], [true], [false], [false]],
70	                [[false], [false], [true], [false]],
71	                [[false], [true], [true], [true]],
72	                [[false], [true], [true], [true]],
73	                [[true], [false], [false], [false]],
74	                [[true], [false], [false], [false]],
75	            ];
76	
77	            criteriaList.forEach((criteriaValue, i) => {
78	                const criteria = new StringValueObject(criteriaValue);
79	
80	                const value = transformToValue(valueObjectCompare(range, criteria).getArrayValue());
81	                expect(value).toStrictEqual(result[i]);
