import type { BaseValueObject } from '../..';
import { ErrorType } from '../../basics/error-type';
import type { compareToken } from '../../basics/token';
import { OPERATOR_TOKEN_COMPARE_SET, OPERATOR_TOKEN_SET, operatorToken } from '../../basics/token';
