                return new ErrorValueObject(ErrorType.NA);
            }

            return resultValue;
        }

        const row = searchArray.binarySearch(value);

        if (row == null) {
            return new ErrorValueObject(ErrorType.NA);
        }

        const resultValue = resultArray.get(row, 0);

        if (resultValue.isNull()) {
            return new ErrorValueObject(ErrorType.NA);
        }

        return resultValue;
    }
}
